SELECT finishedBy AS account, COUNT(*) AS finished, ROUND(SUM(consumed),1) AS hours, ROUND(SUM(estimate),1) AS est, SUM(CASE WHEN deadline NOT IN ('0000-00-00 00:00:00','0000-00-00','') AND finishedDate<=deadline THEN 1 ELSE 0 END) AS ontime, SUM(CASE WHEN deadline NOT IN ('0000-00-00 00:00:00','0000-00-00','') AND finishedDate>deadline THEN 1 ELSE 0 END) AS late FROM zt_task WHERE finishedBy IN ('llh','jiangxuezhe') GROUP BY finishedBy;
SELECT resolvedBy AS account, COUNT(*) AS resolved, SUM(resolution='fixed') AS fixed, SUM(resolution='postponed') AS postponed, SUM(resolution='willnotfix') AS willnotfix, SUM(status='active') AS reopened_active, SUM(severity=1) AS sev1, SUM(severity=2) AS sev2, SUM(severity=3) AS sev3, SUM(severity=4) AS sev4 FROM zt_bug WHERE resolvedBy IN ('llh','jiangxuezhe') GROUP BY resolvedBy;
SELECT actor AS account, COUNT(DISTINCT DATE(date)) AS active_days, COUNT(*) AS actions, MIN(date) AS first_act, MAX(date) AS last_act FROM zt_action WHERE actor IN ('llh','jiangxuezhe') GROUP BY actor;
SELECT actor AS account, COUNT(*) AS actions_30d, COUNT(DISTINCT DATE(date)) AS active_days_30d FROM zt_action WHERE actor IN ('llh','jiangxuezhe') AND date >= '2026-10-10' GROUP BY actor;

